fn bls_pop_from_metadata(
    metadata: &Metadata,
    key: &iroha_data_model::name::Name,
) -> Option<Vec<u8>> {
    let json = metadata.get(key)?;
    let val: JsonValue = norito::json::from_str(json.get()).ok()?;
    match val {
        JsonValue::String(s) => hex::decode(s).ok(),
        _ => None,
    }
}
