        #[test]
        fn empty_block_rejected_during_validation() {
            let kura = Arc::new(Kura::blank_kura_for_testing());
            let query = LiveQueryStore::start_test();
            let leader = crate::block::checked_keypair_with_algorithm(Algorithm::BlsNormal);
            let mut world = World::new();
            insert_consensus_key(
                &mut world,
                "empty-block-validator",
                &leader,
                0,
                None,
                ConsensusKeyStatus::Active,
            );
            let state = State::new_for_testing(world, Arc::clone(&kura), query);
            let (leader_public, leader_private) = leader.into_parts();
            let topology = Topology::new(vec![PeerId::new(leader_public.clone())]);
            // Commit a dummy previous block so the state has height == 1.
            let prev_valid = ValidBlock::new_dummy_and_modify_header(&leader_private, |header| {
                header.set_height(nonzero!(1_u64));
                header.creation_time_ms = 0;
            });
            let prev_committed = prev_valid.commit_unchecked().unpack(|_| {});
            {
                let mut prev_state_block = state.block(prev_committed.as_ref().header());
                let _ = prev_state_block
                    .apply_without_execution(&prev_committed, topology.as_ref().to_owned());
                prev_state_block.commit().unwrap();
            }
            kura.store_block(prev_committed.clone())
                .expect("store previous block");
            let prev_hash = prev_committed.as_ref().hash();
            // Candidate block with no overlays (should be rejected).
            let candidate_block = {
                let valid = ValidBlock::new_dummy_and_modify_header(&leader_private, |header| {
                    header.set_height(nonzero!(2_u64));
                    header.set_prev_block_hash(Some(prev_hash));
                    header.creation_time_ms = 1;
                    header.merkle_root = None;
                });
                let mut signed = SignedBlock::from(valid);
                signed.set_da_proof_policies(Some(
                    crate::da::active_proof_policy_bundle_at_height(
                        &state.nexus_snapshot(),
                        signed.header().height().get(),
                    ),
                ));
                with_current_state_confidential_features(signed, &state, &[(0, &leader_private)])
            };
            let (_handle, time_source) = TimeSource::new_mock(Duration::from_millis(1));
            {
                let mut state_block = state.block(candidate_block.header());
                let validate_result = ValidBlock::validate_replay_fixture(
                    candidate_block.clone(),
                    &topology,
                    &ALICE_ID,
                    &time_source,
                    &mut state_block,
                )
                .unpack(|_| {});
                let err = match validate_result {
                    Ok(_) => panic!("empty block should be rejected"),
                    Err(err) => err,
                };
                assert!(
                    matches!(err.1.as_ref(), BlockValidationError::EmptyBlock),
                    "expected empty-block rejection, got {:?}",
                    err.1
                );
            }
            {
                let mut state_block = state.block(candidate_block.header());
                let events = std::cell::RefCell::new(Vec::new());
                let validate_result = ValidBlock::validate_replay_fixture_with_events(
                    candidate_block.clone(),
                    &topology,
                    &ALICE_ID,
                    &time_source,
                    &mut state_block,
                    |event| {
                        events.borrow_mut().push(event);
                    },
                )
                .unpack(|_| {});
                let err = match validate_result {
                    Ok(_) => panic!("empty block should be rejected"),
                    Err(err) => err,
                };
                assert!(
                    matches!(err.1.as_ref(), BlockValidationError::EmptyBlock),
                    "expected empty-block rejection with events, got {:?}",
                    err.1
                );
                assert!(events.borrow().iter().any(|event| {
                    matches!(
                        event,
                        PipelineEventBox::Block(block_event)
                            if matches!(block_event.status, BlockStatus::Rejected(Reason::EmptyBlock))
                    )
                }));
            }
            let mut v2_voting_block: Option<super::super::VotingBlock> = None;
            let parent_time = state
                .view()
                .latest_block()
                .expect("heartbeat fixture parent")
                .header()
                .creation_time();
            let v2_cadence = candidate_block
                .header()
                .creation_time()
                .saturating_sub(parent_time);
            let v2_result = ValidBlock::validate_sumeragi_v2_candidate_keep_voting_block(
                candidate_block.clone(),
                &topology,
                &ALICE_ID,
                &time_source,
                v2_cadence,
                SumeragiV2ValidationContext::for_body_without_context_bound_attachments(
                    &candidate_block,
                ),
                &state,
                &mut v2_voting_block,
            )
            .unpack(|_| {});
            let error = match v2_result {
                Ok(_) => panic!("Sumeragi v2 must reject a truly idle body"),
                Err(error) => error,
            };
            assert!(matches!(error.1.as_ref(), BlockValidationError::EmptyBlock));
            let mut voting_block: Option<super::super::VotingBlock> = None;
            let result = validate_voting_test_block!(
                candidate_block,
                &topology,
                &time_source,
                &state,
                &mut voting_block
            )
            .unpack(|_| {});
            let err = match result {
                Ok(_) => panic!("empty block should be rejected"),
                Err(err) => err,
            };
            assert!(matches!(err.1.as_ref(), BlockValidationError::EmptyBlock));
        }
        #[test]
        fn v2_validation_is_wall_clock_independent_and_uses_height_context_for_reconfiguration() {
            let kura = Arc::new(Kura::blank_kura_for_testing());
            let query = LiveQueryStore::start_test();
            let leader = crate::block::checked_keypair_with_algorithm(Algorithm::BlsNormal);
            let mut world = World::new();
            insert_consensus_key(
                &mut world,
                "v2-wall-clock-validator",
                &leader,
                0,
                None,
                ConsensusKeyStatus::Active,
            );
            let state = State::new_for_testing(world, Arc::clone(&kura), query);
            let (leader_public, leader_private) = leader.into_parts();
            let topology = Topology::new(vec![PeerId::new(leader_public)]);
            let first =
                commit_block_at_height(&state, &kura, &topology, &leader_private, 1, None, 1);
            let _second = commit_block_at_height(
                &state,
                &kura,
                &topology,
                &leader_private,
                2,
                Some(first),
                2,
            );
            let candidate_at = |creation_time_ms: u64, label: &str| {
                let (_clock, candidate_time) =
                    TimeSource::new_mock(Duration::from_millis(creation_time_ms));
                let transaction_time = TimeSource::new_fixed(Duration::from_millis(999_999));
                let (authority, signer) = gen_account_in(label);
                let transaction = TransactionBuilder::new_with_time_source(
                    state.network_id,
                    authority,
                    &transaction_time,
                    iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
                )
                .with_instructions([Log::new(Level::INFO, label.to_owned())])
                .sign(signer.private_key());
                let accepted = AcceptedTransaction::new_unchecked(Cow::Owned(transaction));
                let parent = state.view().latest_block().expect("audited v2 parent");
                with_current_state_da_sidecars(
                    BlockBuilder::new_with_time_source(vec![accepted], candidate_time)
                        .chain(0, Some(parent.as_ref())),
                    &state,
                )
                .sign(&leader_private)
                .unpack(|_| {})
                .into()
            };
            let candidate: SignedBlock = candidate_at(1_000_000, "v2-wall-clock-work");
            let (_clock, local_time) = TimeSource::new_mock(Duration::ZERO);
            let mut replay_voting_block = None;
            let replay = validate_voting_test_block!(
                candidate.clone(),
                &topology,
                &local_time,
                &state,
                &mut replay_voting_block
            )
            .unpack(|_| {});
            assert!(matches!(
                replay,
                Err(error) if matches!(*error.1, BlockValidationError::BlockInTheFuture)
            ));
            let mut v2_voting_block = None;
            let v2 = ValidBlock::validate_sumeragi_v2_candidate_keep_voting_block(
                candidate.clone(),
                &topology,
                &ALICE_ID,
                &local_time,
                Duration::from_millis(999_998),
                SumeragiV2ValidationContext::for_body_without_context_bound_attachments(&candidate),
                &state,
                &mut v2_voting_block,
            )
            .unpack(|_| {});
            let (valid, staged) = v2.expect(
                "v2 validation must depend on parent time/context, not a validator's wall clock",
            );
            assert_eq!(valid.as_ref().external_transactions().count(), 1);
            assert!(valid.as_ref().error(0).is_some());
            drop(staged);
            let noncanonical: SignedBlock = candidate_at(1_000_001, "v2-noncanonical-time-work");
            let mut noncanonical_voting_block = None;
            let rejected = ValidBlock::validate_sumeragi_v2_candidate_keep_voting_block(
                noncanonical.clone(),
                &topology,
                &ALICE_ID,
                &local_time,
                Duration::from_millis(999_998),
                SumeragiV2ValidationContext::for_body_without_context_bound_attachments(
                    &noncanonical,
                ),
                &state,
                &mut noncanonical_voting_block,
            )
            .unpack(|_| {});
            let error = match rejected {
                Err(error) => error,
                Ok(_) => panic!("non-canonical V2 block time must be rejected"),
            };
            assert!(
                matches!(
                    *error.1,
                    BlockValidationError::NonCanonicalV2BlockTime {
                        expected_ms: 1_000_000,
                        actual_ms: 1_000_001,
                    }
                ),
                "expected non-canonical V2 block time rejection, got {:?}",
                error.1
            );
        }
        #[test]
        fn v2_snapshot_parent_enforces_authenticated_hash_height_and_logical_time() {
            let kura = Arc::new(Kura::blank_kura_for_testing());
            let query = LiveQueryStore::start_test();
            let leader = crate::block::checked_keypair_with_algorithm(Algorithm::BlsNormal);
            let mut world = World::new();
            insert_consensus_key(
                &mut world,
                "v2-snapshot-validator",
                &leader,
                0,
                None,
                ConsensusKeyStatus::Active,
            );
            let state = State::new_for_testing(world, Arc::clone(&kura), query);
            let peer = PeerId::new(leader.public_key().clone());
            let topology = Topology::new(vec![peer.clone()]);
            let first =
                commit_block_at_height(&state, &kura, &topology, leader.private_key(), 1, None, 1);
            let second = commit_block_at_height(
                &state,
                &kura,
                &topology,
                leader.private_key(),
                2,
                Some(first),
                2,
            );
            let audited_parent = state
                .view()
                .latest_block()
                .expect("snapshot parent is available before hash-only conversion");
            assert_eq!(audited_parent.hash(), second);
            kura.force_hash_only_block_for_testing(nonzero!(2_usize))
                .expect("remove audited parent body");
            assert!(state.view().latest_block().is_none());
            let anchor = consensus_v2::SnapshotBootstrapAnchor {
                snapshot_height: 2,
                snapshot_block_hash: second,
                snapshot_block_creation_time_ms: 2,
                snapshot_state_hash: crate::snapshot::canonical_state_snapshot_hash(&state),
            };
            let mut roster_peers = vec![peer];
            roster_peers.extend(
                core::iter::repeat_with(|| {
                    PeerId::new(
                        crate::block::checked_keypair_with_algorithm(Algorithm::BlsNormal)
                            .public_key()
                            .clone(),
                    )
                })
                .take(3),
            );
            roster_peers.sort();
            let roster = roster_peers
                .into_iter()
                .map(|validator| consensus_v2::ValidatorPower {
                    validator,
                    power: 1,
                })
                .collect::<Vec<_>>();
            let context = consensus_v2::HeightContext {
                network_id: state.network_id_ref().clone(),
                protocol_version: consensus_v2::PROTOCOL_VERSION,
                height: 3,
                epoch: 0,
                epoch_end_height: u64::MAX,
                next_epoch_snapshot: None,
                mode: consensus_v2::ConsensusMode::Permissioned,
                parent_commit_qc: None,
                snapshot_bootstrap: Some(anchor),
                quorum: consensus_v2::DualQuorum::from_roster(&roster).expect("fixture quorum"),
                roster,
                nexus_amx_context_hash: Hash::new(b"snapshot validation Nexus/AMX"),
                execution_policy_hash: iroha_crypto::Hash::new(b"test execution policy"),
                da_layout: consensus_v2::DataAvailabilityLayout {
                    encoding: consensus_v2::PayloadEncoding::ReedSolomon16,
                    chunk_size_bytes: 1024,
                    data_shards: 1,
                    parity_shards: 1,
                    max_payload_size_bytes: 4096,
                    max_chunk_count: 8,
                },
                leader_seed: [0x51; 32],
            };
            context.validate().expect("valid snapshot context");
            let candidate_at = |creation_time_ms: u64| {
                let (_clock, candidate_time) =
                    TimeSource::new_mock(Duration::from_millis(creation_time_ms));
                let transaction_time = TimeSource::new_fixed(Duration::from_millis(11));
                let (authority, signer) = gen_account_in("v2-snapshot-parent-work");
                let transaction = TransactionBuilder::new_with_time_source(
                    state.network_id,
                    authority,
                    &transaction_time,
                    iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
                )
                .with_instructions([Log::new(Level::INFO, "v2-snapshot-parent-work".to_owned())])
                .sign(signer.private_key());
                let accepted = AcceptedTransaction::new_unchecked(Cow::Owned(transaction));
                with_current_state_da_sidecars(
                    BlockBuilder::new_with_time_source(vec![accepted], candidate_time)
                        .chain(0, Some(audited_parent.as_ref())),
                    &state,
                )
                .sign(leader.private_key())
                .unpack(|_| {})
                .into()
            };
            let validate = |candidate: SignedBlock, context: &consensus_v2::HeightContext| {
                let mut voting_block = None;
                ValidBlock::validate_sumeragi_v2_candidate_keep_voting_block(
                    candidate,
                    &topology,
                    &ALICE_ID,
                    &TimeSource::new_system(),
                    Duration::from_millis(10),
                    SumeragiV2ValidationContext::from_height_context(context),
                    &state,
                    &mut voting_block,
                )
                .unpack(|_| {})
            };
            let (valid, staged) = validate(candidate_at(12), &context)
                .expect("exact anchor time plus cadence is accepted");
            assert_eq!(valid.as_ref().external_transactions().count(), 1);
            assert!(valid.as_ref().error(0).is_some());
            drop(staged);
            assert!(matches!(
                validate(candidate_at(13), &context),
                Err(error)
                    if matches!(
                        *error.1,
                        BlockValidationError::NonCanonicalV2BlockTime {
                            expected_ms: 12,
                            actual_ms: 13,
                        }
                    )
            ));
            let mut wrong_hash_context = context;
            wrong_hash_context
                .snapshot_bootstrap
                .as_mut()
                .expect("fixture anchor")
                .snapshot_block_hash =
                HashOf::from_untyped_unchecked(Hash::new(b"wrong snapshot parent"));
            assert!(matches!(
                validate(candidate_at(12), &wrong_hash_context),
                Err(error)
                    if matches!(
                        *error.1,
                        BlockValidationError::SnapshotBootstrapParentInvalid(_)
                    )
            ));
        }
